(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞土"]=[{"q": "A qubit driven on its own frequency. What is the chance of 1 after time t?", "a": "sin²(Ωt/2)", "w": ["cos(Ωt)", "Ωt/2", "e^(−Ωt)"], "why": "Driven at its own frequency, it swings."}, {"q": "Driven off frequency by Δ. What ceiling does the chance of 1 never pass?", "a": "Ω²/(Ω² + Δ²)", "w": ["Δ²/(Ω² + Δ²)", "½", "1"], "why": "Off frequency the swing is shallow."}, {"q": "N random turnings of ±ε. How does the average of e^(iθ) fade?", "a": "as (cos ε)ᴺ, about e^(−Nε²/2)", "w": ["as 1/N", "as ε·N", "it does not fade"], "why": "Noise as a small random turning."}, {"q": "Can one gate copy every state of a qubit?", "a": "no: only states equal or at right angles", "w": ["yes, with enough qubits", "yes, if it is slow", "only the state |0⟩"], "why": "No copying."}, {"q": "u|000⟩ + v|111⟩, and two readings: do 1 and 2 agree, do 2 and 3 agree. What do they find?", "a": "which qubit flipped, leaving u and v alone", "w": ["the values of u and v", "whether all three flipped", "nothing about the flip"], "why": "Three qubits against one flip."}, {"q": "d = 2t − 1 qubits, each flipping with chance p. When can the majority’s failure be made as small as wished?", "a": "when p < ¼, by making d larger", "w": ["for any p, with d = 3", "only when p = 0", "when p > ½"], "why": "A threshold."}, {"q": "The grid code below threshold. What does each step from d to d + 2 do to the failure?", "a": "divides it by Λ = p*/p", "w": ["doubles it", "adds p to it", "leaves it alone"], "why": "The grid code."}, {"q": "The swing of a driven qubit. Its accepted name?", "a": "Rabi oscillation", "w": ["Ramsey fringes", "dephasing", "Shor’s swing"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞6"]=[{"q": "A fixed word of k letters in a random string with W starting places. How often is it expected?", "a": "W/4ᵏ times", "w": ["W · 4ᵏ times", "k/W times", "once, always"], "why": "Three billion letters, read both ways."}, {"q": "A 20-letter word in a genome of 3 × 10⁹ letters, both strands. About how often by chance?", "a": "about 0.0055 times", "w": ["about 55 times", "about once", "about 6 × 10⁹ times"], "why": "6 × 10⁹ / 4²⁰."}, {"q": "A full test is made only where a signal appears, with chance q. What happens to the chance matches?", "a": "they are multiplied by q", "w": ["they are divided by q", "they are unchanged", "they vanish"], "why": "A short signal first."}, {"q": "How many words of k letters differ from a given one in exactly j places?", "a": "C(k, j) · 3ʲ", "w": ["kʲ", "4ʲ", "C(k, j)"], "why": "Near matches."}, {"q": "X is a sum of independent 0-or-1 counts with mean μ. A bound on P(X ≥ t) for t > μ?", "a": "e^(−μ)(eμ/t)ᵗ", "w": ["μ/t", "e^(−t)", "t/μ"], "why": "How far the count can stray."}, {"q": "A virus escapes each of m stored stretches with chance q, independently. Chance it escapes all?", "a": "qᵐ", "w": ["mq", "q/m", "1 − qᵐ"], "why": "A memory of past viruses."}, {"q": "The short signal beside the target. Its accepted name?", "a": "the PAM, protospacer adjacent motif", "w": ["the spacer", "the guide RNA", "the repeat"], "why": "The cellar."}, {"q": "The stored stretches in the CRISPR rows. Their accepted name?", "a": "spacers", "w": ["protospacers", "repeats", "guides"], "why": "The cellar."}];
